// Üretilen dosya: tool/ozgun/uret.py. Genel Kültür · Türk kültürü, gelenekler, el sanatları, deyim ve atasözlerinin kökenleri (zor).
const ozCulture2Zor = <(String, String, List<String>, String)>[
  ('Bir ekip, eksik planla bir projeye başlamaktan çekinirken liderleri onları cesaretlendiriyor. Liderin kullanabileceği en uygun atasözü hangisidir?', 'Kervan yolda düzülür.', ['Acele işe şeytan karışır.', 'Sona kalan dona kalır.', 'Ayağını yorganına göre uzat.'], 'Eksikliklerin iş sırasında tamamlanacağını anlatan bu söz, başlamakta tereddüt edenleri yüreklendirir. "Acele işe şeytan karışır" ise tam tersi bir uyarıdır.'),
  ('"Acele işe şeytan karışır." atasözüyle aynı anlamı taşıyan söz hangisidir?', 'Acele ile giden ecele gider.', ['Vakit nakittir.', 'Erken kalkan yol alır.', 'Tez giden tez döner.'], 'İki söz de aceleyle yapılan işin hatalı ya da zararlı sonuçlanacağını anlatır. Diğerleri hızlı davranmayı övmeye yakındır.'),
  ('"Çivi çiviyi söker." atasözü hangi yöntemi anlatır?', 'Bir sorunun benzer bir araçla ya da yöntemle giderilmesini', ['Marangozların çivi yerine tutkal kullanmasını', 'Eski eşyaların atılmasını', 'Bir işi iki kişinin birlikte yapmasını'], 'Bir çiviyi yerinden çıkarmak için başka bir çivi kullanılabildiği gibi, bazı sorunlar da benzeriyle çözülür.'),
  ('"Aba altından değnek göstermek" deyimi neyi anlatır?', 'Görünüşte yumuşak davranırken üstü kapalı biçimde gözdağı vermek', ['Fakir görünüp zengin olmak', 'Değnekle hayvan gütmek', 'Kışın kalın giysi giymek'], 'Aba geniş bir üst giysidir; altından değnek göstermek açık açık söylemeden tehdit etmek anlamına gelir.'),
  ('"Sütten çıkmış ak kaşık" deyimi genellikle nasıl bir bağlamda kullanılır?', 'Suçlu olduğu hâlde kendini temiz ve kusursuz gösteren biri için', ['Mutfağını temiz tutan biri için', 'Yeni doğmuş bir bebek için', 'Süt ürünleri satan biri için'], 'Deyim kusursuzluğu anlatsa da çoğu zaman alaylı biçimde, suçunu gizleyip masum görünen kişiler için söylenir.'),
  ('"Leb demeden leblebiyi anlamak" deyimindeki "leb" sözcüğü hangi dilden gelir ve ne anlama gelir?', 'Farsçadan gelir, dudak demektir.', ['Arapçadan gelir, nohut demektir.', 'Rumcadan gelir, söz demektir.', 'Moğolcadan gelir, kulak demektir.'], 'Farsçada "leb" dudak demektir. Deyim, daha ağız açılmadan söyleneceği anlayacak kadar zeki ve sezgili olmayı anlatır.'),
  ('"Kantarın topuzunu kaçırmak" deyimindeki "topuz" neyi anlatır?', 'Kantarın kolu üzerinde kaydırılan ağırlığı', ['Kantarın tartı kefesini asan zinciri', 'Pazarcının mallarını bağladığı ipi', 'Kantarın taşındığı tahta kızağı'], 'Topuz, kantarın kolunda kaydırılarak dengeyi sağlayan ağırlıktır; fazla kaydırmak ölçüyü aşmak, yani ileri gitmek demektir.'),
  ('"Gemi azıya almak" deyimindeki "gem" sözcüğü neyi anlatır?', 'Atın ağzına takılan demir parçayı', ['Denizde yol alan büyük yelkenli tekneyi', 'Çobanın sürüyü güttüğü sopayı', 'Arabaya bağlanan boyunduruğu'], 'Gem, atın ağzına takılan ve dizginle bağlantılı demirdir. At gemi azı dişleri arasına alırsa denetimden çıkar; deyim söz dinlemez olmayı anlatır.'),
  ('"Fincancı katırlarını ürkütmek" deyiminin kökeni hangi duruma dayanır?', 'Kırılacak mal taşıyan katırların ürkünce yükü kırmasına', ['Kahvehanede fincanların düşüp kırılmasına', 'Katırların dar sokaklarda yolu tıkamasına', 'Fincan falı bakanların insanları korkutmasına'], 'Fincan ve kap kacak taşıyan katırlar ürkerse yükleri kırılırdı. Deyim, güçlü ya da çıkarı olan kişileri kızdıracak bir iş yapmayı anlatır.'),
  ('"Postu kaptırmak" deyimindeki "post" sözcüğü kökeninde neyi anlatır?', 'Tarikat şeyhinin oturduğu deri minderi', ['Yolculara mektup taşıyan ulağı', 'Askerlerin nöbet tuttuğu kulübeyi', 'Saray kapısındaki muhafız birliğinin çadırını'], 'Tekkelerde şeyhin oturduğu hayvan postu makamın simgesiydi. Postu kaptırmak, makamı ya da yeri başkasına kaptırmaktır.'),
  ('"El pençe divan durmak" deyimi hangi eski geleneğe dayanır?', 'Divan toplantılarında görevlilerin elleri önde bağlı, saygıyla ayakta beklemesine', ['Divan edebiyatı şairlerinin şiir okurken el çırpmasına', 'Pehlivanların güreş öncesi selamlaşmasına', 'Kervansaraylarda yolcuların sedirde oturmasına'], 'Osmanlı Divanı\'nda üst makam karşısında elleri kavuşturup ayakta beklemek saygı göstergesiydi. Deyim, birine aşırı saygı ve itaat göstermektir.'),
  ('"Arpa boyu yol gitmek" deyiminde arpa tanesi neden kullanılmıştır?', 'Eskiden arpa tanesi çok küçük bir uzunluk ölçüsü sayıldığı için', ['Arpanın tarlada çok yavaş büyüdüğü bilindiği için', 'Yolculara azık olarak arpa verildiği için', 'Arpa ekili tarlalarda yürümek zor olduğu için'], 'Arpa tanesinin boyu geleneksel olarak en küçük uzunluk birimlerinden biriydi. Deyim, çok az ilerleme kaydetmeyi anlatır.'),
  ('"Yorgan gitti, kavga bitti." sözü hangi durumu anlatmak için kullanılır?', 'Asıl amacın ele geçirilmesiyle tartışmanın sona ermesini', ['Kış bitince evlerde yorgan kaldırılmasını', 'Bir kavgada iki tarafın da barışmasını', 'Eski eşyaların yenileriyle değiştirilmesini'], 'Nasreddin Hoca fıkrasında dışarıdaki kavgaya bakmaya çıkan Hoca\'nın yorganı çalınır; kavganın yorgan için çıktığı anlaşılır. Söz, çekişmenin asıl nedeninin ortaya çıktığı durumlarda söylenir.'),
  ('"Dimyat\'a pirince giderken evdeki bulgurdan olmak" deyimindeki Dimyat neresidir?', 'Mısır\'da bir liman kenti', ['Anadolu\'da bir pirinç ovası', 'İran\'da bir ticaret yolu', 'Suriye\'de bir kervansaray'], 'Dimyat (Damietta), Nil deltasında bir liman kentidir ve eskiden pirinç ticaretiyle ünlüydü. Deyim, daha fazlasını isterken elindekini de yitirmeyi anlatır.'),
  ('Daha yüksek maaş vaat eden bir işe geçmek için istifa eden ama o işi de alamayan kişinin durumu hangi deyimle anlatılır?', 'Dimyat\'a pirince giderken evdeki bulgurdan olmak', ['Ateş olsa cürmü kadar yer yakar', 'Kaş yapayım derken göz çıkarmak', 'Eşeğini sağlam kazığa bağlamak'], 'Daha iyisini ararken elde olanı da kaybetmek tam olarak bu deyimle anlatılır. Kaş yapayım derken göz çıkarmak ise düzeltme çabasıyla işi bozmaktır.'),
  ('"Kel başa şimşir tarak" sözünde tarağın şimşirden seçilmesi neyi vurgular?', 'Tarağın değerli ve kaliteli olmasını', ['Tarağın çok kırılgan olmasını', 'Tarağın ucuz ve sıradan olmasını', 'Tarağın yalnız hamamda kullanılmasını'], 'Şimşir, sert ve sık dokulu yapısıyla değerli bir ağaçtır; ondan yapılan tarak özenli bir eşya sayılırdı.'),
  ('"Ateş olsa cürmü kadar yer yakar." sözü hangi durumda kullanılır?', 'Birinin etkisinin ve zararının sınırlı olduğu belirtilirken', ['Yangın tehlikesine karşı önlem alınırken', 'Kışın evlerin ısıtılması konuşulurken', 'Bir işin çok hızlı bittiği anlatılırken'], 'Cürüm burada büyüklük, hacim anlamındadır. Söz, birinin gücünün zarar verebileceği alanın küçük olduğunu anlatır.'),
  ('Bir dokumacı mavi ipliği çivitle, sarı ipliği cehriyle boyamıştır. Yeşil elde etmek için ne yapması en uygundur?', 'İpliği önce cehriyle, sonra çivitle boyamak', ['İpliği yalnız kökboya ile uzun süre kaynatmak', 'Cehri ile kökboyayı karıştırıp tek seferde boyamak', 'Boyanmış mavi ipliği güneşte soldurmak'], 'Geleneksel boyacılıkta yeşil, sarı ve mavi boyaların üst üste uygulanmasıyla elde edilir. Kökboya kırmızı verdiği için yeşil oluşturmaz.'),
  ('Bir kilimde akrep ve yengeç motiflerine yer verilmesinin geleneksel amacı nedir?', 'Kötülükten ve zararlı hayvanlardan korunmak', ['Dokumacının doğum yerini belirtmek', 'Kilimin satış fiyatını yükseltmek', 'Kilimin hangi mevsimde dokunduğunu göstermek'], 'Halk inancına göre zararlı varlığın biçimini dokumak, ondan korunmayı sağlar; bu motifler koruyucu, nazar engelleyici anlam taşır.'),
  ('15. ve 16. yüzyıl Avrupa resimlerinde sıkça görüldüğü için bazı Anadolu halıları hangi ressamların adıyla anılır?', 'Holbein ve Lotto', ['Rembrandt ve Vermeer', 'Monet ve Renoir', 'Picasso ve Braque'], 'Hans Holbein ve Lorenzo Lotto\'nun tablolarında görülen Uşak bölgesi halıları sanat tarihinde "Holbein halısı" ve "Lotto halısı" diye anılır.'),
  ('Cicim dokumasını kilimden ayıran özellik hangisidir?', 'Desenin zemine ek renkli ipliklerle sonradan işlenmesi', ['Desenin düğümlenerek kabarık hav oluşturması', 'Yalnızca tek renk iplikle hiç desensiz dokunması', 'Tezgâh kullanılmadan elde örülerek yapılması'], 'Cicimde düz dokunan zemine desen ipliği ayrıca eklenir; böylece motif yüzeyde kabartı gibi görünür. Kilimde ise desen atkıların kendisiyle oluşur.'),
  ('Bir ebru ustası önce serptiği boya halkalarının çok küçük kaldığını, yayılmadığını fark ediyor. Sorunu çözmek için en uygun işlem hangisidir?', 'Boyaya biraz daha öd eklemek', ['Teknedeki suya daha fazla kitre koymak', 'Boyayı ateşte kaynatıp koyulaştırmak', 'Kâğıdı suya daha uzun süre bastırmak'], 'Öd boyanın yayılma gücünü artırır. Kitre eklemek ise suyu daha da koyulaştırıp boyanın yayılmasını güçleştirebilir.'),
  ('Geleneksel ebru fırçaları hangi malzemelerden yapılır?', 'At kılı ve gül dalı', ['Kuş tüyü ve bambu', 'Domuz kılı ve meşe dalı', 'Keçi kılı ve kamış'], 'Ebru fırçaları gül dalından bir sapa at kılı bağlanarak hazırlanır; bu fırçayla boyalar suya serpilir.'),
  ('Ebru sanatında lale, gelincik, karanfil gibi çiçek motiflerinin yapılmasıyla tanınan usta kimdir?', 'Necmeddin Okyay', ['Mustafa Rakım', 'Hafız Osman', 'Matrakçı Nasuh Efendi'], 'Necmeddin Okyay, 20. yüzyılda çiçekli ebruyu geliştirmesiyle tanınır; bu türe onun adıyla "Necmeddin ebrusu" da denir.'),
  ('Bir hattat aharlı kâğıda yazarken bir harfi yanlış yazıyor. Aharlı kâğıdın bu durumda sağladığı avantaj nedir?', 'Mürekkep kâğıda işlemediği için hatanın kazınarak düzeltilebilmesi', ['Mürekkebin kendiliğinden buharlaşıp kaybolması', 'Kâğıdın suya batırılınca yeniden beyazlaması', 'Hatalı harfin üzerine altın yaldız sürülebilmesi'], 'Ahar tabakası mürekkebin kâğıt liflerine işlemesini önler; bu yüzden hatalı kısım dikkatle kazınıp silinebilir.'),
  ('Hattatın kalemi açarken ucunu kesmek için altına koyduğu kemik ya da fildişi levhaya ne ad verilir?', 'Makta', ['Mühre taşı', 'Divit', 'Hokka'], 'Makta, kalem ucunun kesildiği sert altlıktır. Mühre kâğıdı parlatmaya, hokka mürekkep koymaya, divit ise kalem taşımaya yarar.'),
  ('Hat sanatında harflerin boyutu ve oranları nasıl ölçülür?', 'Kalemle konan eşkenar dörtgen biçimli noktalarla', ['Cetvelle çizilen santimetre çizgileriyle', 'Kâğıdın kenarına göre parmak eniyle', 'Pergelle çizilen dairelerin çapıyla'], 'Hattatlar kalemin ucuyla eşkenar dörtgen noktalar koyar; her harfin yüksekliği ve genişliği bu noktaların sayısıyla belirlenir.'),
  ('Tezhip sanatında kıvrık dallar üzerine yerleştirilen, stilize edilmiş çiçek ve yaprak motiflerine verilen genel ad hangisidir?', 'Hatai', ['Rumi', 'Bulut', 'Münhani'], 'Hatai üslubu stilize çiçek ve yapraklardan oluşur. Rumi ise hayvan biçimlerinden soyutlanmış kıvrık motiflerdir.'),
  ('16. yüzyıl İznik çinilerinde görülen, yüzeyden hafifçe kabarık parlak kırmızı renge verilen ad hangisidir?', 'Mercan kırmızısı', ['Kubadabad moru', 'Selçuklu firuzesi', 'Kütahya sarısı'], 'Kırmızı, demir oksitçe zengin bir boyayla elde edilir ve sırın altında kabarık durur. Bu renk İznik\'in en parlak döneminin simgesidir.'),
  ('Çinide desenin önce gövdeye çizilip boyanması, ardından üzerine şeffaf sır sürülüp fırınlanması tekniğine ne ad verilir?', 'Sıraltı tekniği', ['Mozaik çini tekniği', 'Lüster tekniği', 'Minai tekniği'], 'Sıraltında boya sırın altında kalır ve böylece korunur. Lüsterde metalik parıltı, minaide ise sırın üzerine renkli boyalar uygulanır.'),
  ('Bir çömlekçi, çamurdan biçimlendirdiği testiyi kurutmadan doğrudan fırına veriyor ve testi çatlıyor. Bunun en olası nedeni nedir?', 'İçindeki suyun ani ısınıp buharlaşması', ['Kilin içinde hiç su bulunmaması', 'Fırın sıcaklığının gereğinden çok düşük tutulması', 'Testinin sırla kaplanmamış olması'], 'Kurutulmamış çamurdaki su fırında birden buhara dönüşür ve genişleyerek gövdeyi çatlatır. Bu yüzden ürünler önce yavaşça kurutulur.'),
  ('Kalaycılar kalaylama sırasında kabın yüzeyini temizleyip kalayın tutunmasını sağlamak için hangi maddeyi kullanır?', 'Nişadır', ['Şap', 'Kireç', 'Tuz ruhu'], 'Nişadır (amonyum klorür) sıcak bakırın yüzeyindeki oksidi temizler. Böylece eriyen kalay yüzeye düzgün yayılır.'),
  ('Bakır ya da pirinç üzerine altın yaldız uygulanarak yapılan Osmanlı metal işçiliğine ne ad verilir?', 'Tombak', ['Telkari', 'Savat', 'Kalemkâr'], 'Tombak işlerinde altın civa ile karıştırılıp bakır yüzeye sürülür; civa ısıtılarak uçurulunca altın kaplama kalır.'),
  ('Gümüş yüzeye kazınan desenlerin içine siyah renkli bir alaşım doldurulmasıyla yapılan ve Van ile özdeşleşen işçilik hangisidir?', 'Savat', ['Telkari', 'Tombak', 'Kündekari'], 'Savat işinde gümüş, bakır, kurşun ve kükürtle hazırlanan koyu alaşım oyuklara doldurulur; böylece gümüş üzerinde siyah desen belirir.'),
  ('Selçuklu camilerindeki minberlerde kündekari tekniğinin tercih edilmesinin en önemli yararı nedir?', 'Ahşabın ısı ve nemle genleşip daralmasına uyum sağlaması', ['Minberin tek parça ağaçtan yontulabilmesi', 'Ahşabın yanmaz hâle gelmesi', 'Minberin kolayca sökülüp taşınması'], 'Parçalar birbirine sıkıca yapıştırılmadığı için ahşap hareket etse de çatlamaz; bu yüzden kündekari eserler yüzyıllarca dayanmıştır.'),
  ('Bir yazmacı, üç renkli bir motifi tahta kalıplarla basacaktır. Geleneksel yönteme göre en uygun yol hangisidir?', 'Her renk için ayrı kalıp hazırlayıp sırayla basmak', ['Tek kalıba üç rengi birden sürüp tek seferde basmak', 'Önce kumaşı tümüyle boyayıp desenleri ağartmak', 'Motifin dış çizgisini basıp içini iğneyle işlemek'], 'Çok renkli yazmada her renk ayrı kalıpla ve doğru hizada basılır; böylece renkler birbirine karışmaz.'),
  ('Doğu Karadeniz yöresinde keten liflerinden dokunan, "feretiko" olarak da bilinen geleneksel kumaş hangisidir?', 'Rize bezi', ['Şile bezi ya da Şile dokuması', 'Kutnu', 'Ehram'], 'Rize bezi keten ipliğinden dokunur; serin ve dayanıklı olduğu için gömlek ve örtülerde kullanılmıştır.'),
  ('Erzurum yöresinde kadınların dışarı çıkarken büründüğü, ince yünden dokunmuş geleneksel örtü hangisidir?', 'Ehram', ['Bindallı', 'Cepken', 'Kepenek'], 'Ehram, Erzurum\'a özgü ince yün dokumadır ve yöreye özgü desenler taşır.'),
  ('Bir keçeci, sabunlu sıcak suyla ıslattığı yün katmanını saatlerce yuvarlayıp ezdikten sonra sağlam bir yüzey elde ediyor. Bu yüzeyin oluşmasını sağlayan temel etken nedir?', 'Sürtünme ve basınçla yün liflerinin birbirine kilitlenmesi', ['Suyun buharlaşıp yünü taşa dönüştürmesi', 'Sabunun yapıştırıcı gibi kuruyup sertleşmesi', 'Yünün yuvarlanırken kendiliğinden iplik hâline gelip dokunması'], 'Yün liflerinin yüzeyindeki pulcuklar ıslaklık, ısı ve hareketle açılıp birbirine geçer; böylece lifler sıkıca kenetlenir.'),
  ('Lületaşı ustalarının taşı ocaktan çıkar çıkmaz işlemeyi tercih etmesinin nedeni nedir?', 'Taşın nemliyken daha yumuşak olup kolay oyulması', ['Taşın havayla temas edince eriyip toz hâline gelerek kaybolması', 'Taşın yalnız gece işlenebilmesi', 'Taşın kuruyunca renginin karaya dönmesi'], 'Lületaşı ocaktan çıktığında nemli ve yumuşaktır, kurudukça sertleşir. Bu yüzden oyma işi taş nemliyken daha kolay yapılır.'),
  ('Karadeniz yöresinde horon oynayan erkeklerin giydiği, üst kısmı bol, baldırdan aşağısı dar pantolona ne ad verilir?', 'Zıpka', ['Dizlik', 'Şalvar entari', 'Potur'], 'Zıpka, Doğu Karadeniz erkek giyiminin parçasıdır; hareketi kolaylaştıran kesimi horon gibi hızlı oyunlara uygundur.'),
  ('Karagöz ve orta oyunu karakterlerinin başında görülen, kumaşla kaplı büyük başlığa ne ad verilir?', 'Kavuk', ['Fes', 'Kalpak', 'Hotoz'], 'Kavuk, sarık sarılarak giyilen ya da sarıksız kullanılan bir erkek başlığıdır. "Kavuk devretmek" sözü orta oyunundan gelir.'),
  ('Düğün davetiyesiyle birlikte konuklara gönderilen mendil, lokum ya da şeker gibi küçük armağana ne ad verilir?', 'Okuntu', ['Yüz görümlüğü', 'Başlık', 'Çeyiz'], 'Okuntu, düğüne davet edilen kişiye davetle birlikte sunulan simgesel armağandır. Yüz görümlüğü ise damadın geline verdiği hediyedir.'),
  ('Gelin baba evinden çıkarken beline kırmızı bir kuşak bağlanır. Bu kuşağı geleneksel olarak kim bağlar?', 'Gelinin babası ya da erkek kardeşi', ['Damadın en yakın arkadaşı', 'Mahallenin en yaşlı kadını', 'Düğünü yöneten çalgıcı'], 'Kırmızı kuşak, gelinin erdemini ve ailesinin onu güvenle uğurladığını simgeler; bu görev geleneksel olarak babaya ya da erkek kardeşe düşer.'),
  ('Kız isteme sırasında söylenen "Allah\'ın emri, Peygamber\'in kavliyle" sözündeki "kavil" ne anlama gelir?', 'Söz', ['Kitap', 'Ev', 'Yol'], 'Kavil, Arapça kökenli bir sözcüktür ve "söz" anlamına gelir. Kız isteyen aile bu kalıp sözle niyetini dile getirir.'),
  ('Yürümeye başlayan çocuğun ayakları arasına ip bağlanıp bu ipin kesilmesi geleneğine ne ad verilir?', 'Paça kesme', ['Kırklama', 'Beşik kertme', 'Diş hediği'], 'Paça kesmede ip, çocuğun yürümesini engelleyen bağı simgeler; ipin kesilmesiyle çocuğun düzgün ve çabuk yürüyeceğine inanılır.'),
  ('Osmanlı mezar taşlarında erkek mezarlarının baş taşına oyulan sarık, kavuk ya da fes biçimi neyi gösterirdi?', 'Ölenin mesleği, rütbesi ya da bağlı olduğu yol', ['Ölenin kaç yıl yaşadığı', 'Ölenin hangi mevsimde öldüğü', 'Ölenin kaç çocuğu olduğu'], 'Başlık biçimleri yeniçeri, kadı, derviş ya da paşa gibi toplumsal konumları gösterirdi. Kadın mezar taşlarında ise genellikle çiçek ve süsleme görülür.'),
  ('Eski Türklerde hükümdarın halka verdiği büyük ziyafet aynı zamanda devlet işlerinin görüşüldüğü bir toplantıya dönüşürdü. Bu şölenlere ne ad verilir?', 'Toy', ['Yuğ', 'Sığır', 'Ordu'], 'Toy, hükümdarın düzenlediği ziyafettir. Halkın kağana bağlılığını gösterdiği ve önemli kararların duyurulduğu bir buluşmaydı.'),
  ('Halk takviminde yıl, Hızır Günleri ve Kasım Günleri olarak ikiye ayrılır. Hızır Günleri hangi dönemi kapsar?', '6 Mayıs\'tan 8 Kasım\'a kadar süren yaz yarısını', ['21 Mart\'tan 21 Haziran\'a kadar süren bahar dönemini', '1 Ocak\'tan 1 Temmuz\'a kadar süren ilk yarıyı', '8 Kasım\'dan 6 Mayıs\'a kadar süren kış yarısını'], 'Halk takvimi Hıdırellez ile başlayan sıcak yarıyı Hızır Günleri, Kasım ile başlayan soğuk yarıyı Kasım Günleri sayar.'),
  ('Kış ortasında ince giyinip üşümüş görünmeyen kişiler için kullanılan "zemheri zürafası" sözünün mizahı neye dayanır?', 'Yılın en soğuk döneminde mevsime uymayan hafif giysilerle dolaşmaya', ['Zürafaların kış uykusuna yatmasına', 'Kışın boyun ağrısı çekilmesine', 'Uzun boylu insanların soğuğa dayanıklı olmasına'], 'Zemheri yılın en soğuk dönemidir; bu dönemde ince giyinen kişi sıra dışı ve gösterişli görüldüğü için alaycı biçimde zürafaya benzetilir.'),
  ('Odun ateşinin yerine sıcak kumun kullanıldığı kahve pişirme yönteminin sağladığı başlıca yarar nedir?', 'Isının yavaş ve eşit dağılarak kahvenin taşmadan pişmesi', ['Kahvenin hiç ısıtılmadan demlenebilmesi', 'Kahvenin içine kum karışarak yoğunlaşması', 'Cezvenin rengini değiştirmesi'], 'Kızgın kum ısıyı cezvenin her yanına yavaşça iletir; kahve yavaş ısındığı için köpüğünü korur.'),
  ('Türk hamamını Roma hamamından ayıran önemli fark hangisidir?', 'Durgun bir havuza girmek yerine akan ve dökünülen suyla yıkanılması', ['Hamamın yalnız açık havada inşa edilmesi', 'Hamamda ısıtma için hiç ateş kullanılmaması', 'Hamama yalnız kışın girilebilmesi'], 'Türk hamamında havuzda yıkanma yoktur; kurnadan tasla alınan su vücuda dökülür. Bu, temizliğin akan suyla yapılması anlayışına dayanır.'),
  ('Hamamın ısıtıldığı ocak bölümünün adından türeyen "külhanbeyi" sözü bugün nasıl bir kişiyi anlatır?', 'Kabadayılık taslayan, kavgacı kişiyi', ['Hamam işleten zengin esnafı', 'Çok temiz ve titiz kişiyi', 'Ateş yakmakta usta kişiyi'], 'Eskiden hamam ocaklarının sıcak külhanlarında barınan kimsesiz ve serseri gençler bu adla anılırdı. Sözcük zamanla kabadayı anlamı kazanmıştır.'),
  ('Karagöz oyununun bölümleri sırasıyla hangisinde doğru verilmiştir?', 'Mukaddime, muhavere, fasıl, bitiş', ['Muhavere, mukaddime, bitiş ve en son fasıl', 'Fasıl, mukaddime, muhavere, bitiş', 'Mukaddime, fasıl, bitiş, muhavere'], 'Oyun Hacivat\'ın perde gazeliyle başlayan mukaddimeyle açılır, iki karakterin söyleşmesi olan muhavereyle sürer, asıl konunun işlendiği fasıl ve kapanış konuşmasıyla biter.'),
  ('Orta oyunundan gelen "kavuk devretmek" sözü ne anlama gelir?', 'Usta oyuncunun rolünü ve mirasını kendinden sonrakine bırakması', ['Bir giysiyi başkasına armağan etmek', 'Bir oyunu yarıda kesip seyirciden özür dilemek', 'Sahnede başlıkları değiştirip yeni tipler yaratmak'], 'Kavuklu rolü bir ustalık makamı sayılır; usta, kavuğunu yetiştirdiği oyuncuya devrederek ona bu rolü ve sorumluluğu emanet ederdi.'),
  ('Karagöz, orta oyunu ve meddahın ortak özelliği olarak hangisi söylenebilir?', 'Toplumdaki farklı tipleri taklit ederek güldürmeleri', ['Üçünün de perde arkasında renkli tasvirlerle oynatılması', 'Üçünün de tek bir oyuncu tarafından sergilenmesi', 'Üçünün de yazılı bir metinden okunarak sunulması'], 'Üç türde de mahalle yaşamındaki farklı kişiler, ağızlar ve meslekler taklit edilir; gülmece bu tiplerin çatışmasından doğar.'),
  ('Bir âşık lebdeğmez söylerken aşağıdaki sözcüklerden hangisini kullanamaz?', 'Bahar', ['Sırrı ya da sırlar', 'Yaşar', 'Dilek'], '"Bahar" sözcüğündeki "b" sesi dudakların birleşmesiyle çıkar ve lebdeğmezde yasaktır. Diğer sözcüklerde dudak ünsüzü yoktur.'),
  ('Bir manide birinci dizenin yedi heceden az olup cinaslı bir sözcükle kurulmasına ne ad verilir?', 'Kesik mani', ['Artık mani', 'Düz mani', 'Yedekli mani'], 'Kesik manide ilk dize kısadır ve cinaslı uyak taşır. Böylece söyleyiş oyunlu ve zekice bir hâl alır.'),
  ('Orta Anadolu\'da, özellikle Kırşehir ve çevresinde söylenen, yüksek perdeden başlayan uzun hava türü hangisidir?', 'Bozlak', ['Horon', 'Zeybek havası', 'Hoyrat'], 'Bozlak, Türkmen kökenli uzun hava türüdür. Hoyrat ise daha çok Kerkük ve Doğu Anadolu\'da söylenen uzun havadır.'),
  ('Kazan doğurdu fıkrasında komşunun düştüğü durumu en iyi anlatan sonuç hangisidir?', 'Çıkarına uygun saçmalığa inanan kişi, aynı mantık aleyhine işleyince itiraz edemez.', ['Komşuluk ilişkilerinde ödünç vermek her zaman zarar getirir.', 'Yaşlı eşyalar zamanla kendiliğinden bozulup kullanılmaz olur.', 'Bir şeyi geri istemek komşuluğa uymayan bir davranıştır.'], 'Komşu, kazanın doğurduğuna kazançlı çıktığı için inanmıştır. Aynı mantıkla kazanın öldüğünü de kabul etmek zorundadır.'),
  ('Dede Korkut hikâyelerinde çocuklara adın ancak bir kahramanlık gösterdikten sonra verilmesi Oğuz toplumunun hangi değerini yansıtır?', 'Kişinin değerinin yiğitliğiyle ölçülmesini', ['Çocukların tümüyle annelerine bağlı kalmasını', 'Adların her zaman büyükbabalardan devralınmasını', 'Ad vermenin yalnızca din adamlarının görevi olmasını'], 'Ad, gencin topluma yararlı bir yiğit olduğunun kanıtıdır. Bu gelenek savaşçı ve göçebe bir toplumun kahramanlığa verdiği önemi gösterir.'),
  ('Dede Korkut mirası UNESCO listesine hangi ülkelerin ortak başvurusuyla alınmıştır?', 'Azerbaycan, Kazakistan ve Türkiye', ['Türkmenistan, Özbekistan ve Kırgızistan', 'İran, Irak ve Türkiye', 'Gürcistan, Ermenistan ve Azerbaycan'], '"Dede Korkut Mirası, Destan Kültürü, Halk Hikâyeleri ve Müziği" 2018\'de bu üç ülkenin ortak başvurusuyla listeye girmiştir.'),
  ('Köroğlu\'nun sığınağı olarak anlatılan ve adıyla anılan yer hangisidir?', 'Çamlıbel', ['Kazdağı', 'Erciyes', 'Ağrı Dağı'], 'Köroğlu, Çamlıbel\'de yiğitlerini toplayıp haksızlık yapan beylere karşı mücadele eder. Halk anlatısında adaletsizliğe başkaldırının simgesidir.'),
  ('Halk hikâyelerinin anlatımını masallardan ayıran özellik hangisidir?', 'Düzyazı bölümlerin arasında koşma ve türkülerin söylenmesi', ['Anlatının yalnızca yazılı kitaplardan okunması', 'Bütün kahramanların hayvanlardan oluşması', 'Hikâyenin her zaman tek cümleyle bitmesi'], 'Halk hikâyesinde âşık, olayları düzyazıyla anlatır; duygunun yoğunlaştığı yerlerde sazıyla şiir söyler. Masallar ise genellikle yalnız düzyazıdır.'),
  ('Bağlamanın mızrap kullanılmadan, parmaklarla tellere vurularak çalınmasına ne ad verilir?', 'Şelpe', ['Tezene vuruşu', 'Tremolo ya da tarama', 'Pizzikato vuruşu'], 'Şelpe tekniğinde sağ ve sol el parmakları tellere vurur ve çeker. Özellikle Orta Anadolu ve Teke yöresinde yaygındır.'),
  ('Mesnevi\'nin başında neyin kamışlıktan koparılışından yakınması hangi duygunun simgesi olarak yorumlanır?', 'İnsanın asıl kaynağından ayrılmanın verdiği özlem', ['Müzikçilerin yorgunluğu ve çalgılarına küsüp onları bırakması', 'Kamışlıkların kurutulmasına duyulan öfke', 'Neyin sesinin diğer çalgılardan zayıf olması'], 'Mevlana\'ya göre ney, kamışlıktan ayrıldığı için inler; bu da insan ruhunun özüne kavuşma özlemini simgeler.'),
  ('Osmanlı\'da okçuların menzil atışlarında elde ettikleri dereceleri göstermek için dikilen taşlara ne ad verilir?', 'Menzil taşı ya da nişan taşı', ['Balbal ve kurgan taşı', 'Mihenk taşı', 'Sadaka taşı'], 'İstanbul\'daki Okmeydanı\'nda rekor atışlar, okun düştüğü yere dikilen taşlarla işaretlenirdi. Taşların üzerine atıcının adı ve atış uzaklığı yazılırdı.'),
  ('Yay yapımından atış tekniklerine kadar uzanan geleneksel Türk okçuluğu, UNESCO\'nun somut olmayan miras listesine hangi yılda kaydedilmiştir?', '2019', ['2008', '2010', '2014'], 'Geleneksel Türk okçuluğu 2019\'da listeye girmiştir. Bu miras yay yapımından atış tekniklerine kadar bütün bilgi ve törenleri kapsar.'),
  ('Ahilikte kalfalıktan ustalığa geçen kişi için düzenlenen törende beline kuşak bağlanmasına ne ad verilir?', 'Şed kuşanma', ['Kılıç kuşanma', 'Kavuk devretme', 'Alay giyme'], 'Şed, ustalık simgesi olan kuşaktır. Tören, kişinin mesleği bağımsız olarak yürütmeye hak kazandığını herkese duyurur.'),
  ('Osmanlı esnaf düzeninde bir kişinin belirli bir zanaatı icra edip dükkân açabilmesi için sahip olması gereken hakka ne ad verilirdi?', 'Gedik', ['Tımar', 'Berat', 'İltizam'], 'Gedik, sınırlı sayıda verilen ve esnaflık yapma hakkı sağlayan bir ayrıcalıktı. Böylece bir meslekteki dükkân sayısı denetim altında tutulurdu.'),
  ('Ramazan aylarında hayırseverlerin bakkala gidip, kime ait olduğunu bilmeden veresiye defterindeki borçları ödemesi geleneğine ne denir?', 'Zimem defteri silme', ['Fitre dağıtma', 'Kese açma', 'Kuyu kazma'], 'Hayırsever, defterin birkaç sayfasındaki borçları öder ve sayfaları siler. Borcu ödenen kişi de kimin ödediğini öğrenmez.'),
  ('Osmanlı\'da bazı vakıfların yaralı leyleklerin ve göçmen kuşların bakımı için kurulmuş olması vakıf anlayışı hakkında ne gösterir?', 'Hayırseverliğin yalnızca insanlarla sınırlı tutulmadığını', ['Vakıfların asıl amacının hayvan ticareti olduğunu', 'Kuşların devlet malı sayıldığını', 'Vakıfların yalnız sarayın emriyle kurulduğunu'], 'Vakıf kültüründe iyilik bütün canlıları kapsar. Hasta kuşlara, sokak hayvanlarına bakmak için de vakıflar kurulmuştur.'),
  ('Bir vakıf kuran kişinin, vakfın amacını, gelirlerini ve nasıl yönetileceğini yazdığı belgeye ne ad verilir?', 'Vakfiye', ['Tapu senedi', 'Ahidname', 'Siyasetname'], 'Vakfiye, vakfın anayasası gibidir. Vakfedilen mallar ve bunlardan elde edilecek gelirin nerelere harcanacağı bu belgede belirtilir.'),
  ('Kuraklık zamanlarında çocukların bir kepçeyi bebek gibi giydirip kapı kapı dolaşarak yağmur istediği törene ne ad verilir?', 'Çömçe gelin', ['Saya gezmesi', 'Koç katımı', 'Gelin hamamı'], 'Çömçe kepçe demektir. Kapısına gelinen ev sahipleri çocuklara un, yağ gibi yiyecekler verir ve kepçeye su döker; topluca yağmur dilenir.'),
  ('Kuşköy\'deki ıslık dilinin ortaya çıkışını en iyi açıklayan coğrafi etken hangisidir?', 'Evlerin dik yamaçlara dağınık kurulup aralarında uzaklık olması', ['Bölgede hiç rüzgâr esmemesi', 'Köyün düz bir ovada toplu yerleşmesi', 'Halkın konuşma dilini bilmemesi'], 'Dağınık yerleşilen dik vadilerde bağırmak yetersiz kalır. Islık sesi daha uzaklara ulaşır ve vadi boyunca anlaşılabilir.'),
  ('Geleneksel Türk evinde bir odanın yatmak, oturmak, yemek yemek ve yıkanmak için kullanılabilmesi hangi özelliğinden kaynaklanır?', 'Yüklük, sedir ve ocak gibi öğelerle her odanın küçük bir ev gibi düzenlenmesi', ['Odaların her birinin ayrı bir binada yer alması', 'Evlerde hiç mobilya ve dolap bulunmaması', 'Odaların duvarlarının hareketli perdelerden yapılması'], 'Gündüz toplanan yataklar, duvar boyunca uzanan sedirler ve odadaki ocak, odayı çok işlevli kılar; bu yüzden her odaya "ev içinde ev" denir.'),
  ('Karadeniz\'de tahıl saklamak için kullanılan ahşap ambarların yüksek ayaklar üzerine kurulmasının başlıca nedeni nedir?', 'Ürünü nemden ve farelerden korumak', ['Ambarın uzaktan görülmesini sağlamak', 'Tahılın güneşte daha çabuk kurumasını engellemek', 'Ambarın içine hayvanların da sığmasını sağlamak'], 'Serender adı verilen bu ambarlar yerden yüksek tutulur; ayakların üstündeki geniş tablalar farelerin tırmanmasını engeller.'),
  ('Yörüklerin keçi kılından dokunan kara çadırları yağmurlu havada neden su geçirmez?', 'Kıllar ıslanınca şişip dokunun aralıklarını kapatır.', ['Çadırın üzeri her yağmurdan önce balmumuyla kaplanır.', 'Keçi kılı suyu tümüyle iterek hiç ıslanmaz.', 'Çadır yağmurda yere yatırılıp üstü örtülür.'], 'Keçi kılı ıslandıkça kabarır ve dokuma sıkılaşır; kuruduğunda ise aralıklar açılarak çadırın içi havalanır.'),
  ('Osmanlı\'da varlıklı konaklarda iftara davet edilen konuklara yemekten sonra verilen armağana ne ad verilirdi?', 'Diş kirası', ['Yüz görümlüğü', 'Okuntu ya da davetiye', 'Bahşiş ya da kese'], 'Diş kirası, konuğun dişini yorduğu için ona sunulan küçük bir hediyedir. Ramazan\'da konukseverliğin ve cömertliğin simgesidir.'),
  ('Selçuklu ve Osmanlı süslemesinde üç benek ile iki dalgalı çizgiden oluşan ve güç ile egemenliği simgeleyen motif hangisidir?', 'Çintemani', ['Rumi ya da palmet', 'Hatai ya da pençberk', 'Bulut ya da çiçek'], 'Çintemani üç top ve iki dalgalı şeritten oluşur. Kaftanlarda ve kumaşlarda sıkça görülen bu motif şans ve güç anlamı taşır.'),
  ('Osmanlı sanatında İznik çinilerinden kaftanlara kadar en çok kullanılan, lalenin yanı sıra en sevilen çiçek motiflerinden olan çiçek hangisidir?', 'Karanfil', ['Ayçiçeği ya da nergis', 'Orkide ya da manolya', 'Papatya ya da gelincik'], 'Lale, karanfil, sümbül ve gül klasik Osmanlı süslemesinin "dört çiçeği" sayılır. Karanfil özellikle 16. yüzyıl çinilerinde çok görülür.'),
  ('Anadolu Selçuklu döneminde Mengücekliler tarafından yaptırılan Divriği Ulu Camii\'nin taş kapıları dünyaca ünlüdür. Bu kapıların önemini en iyi açıklayan özellik hangisidir?', 'Taş üzerine son derece ayrıntılı ve kabartmalı bitkisel-geometrik süslemeler içermesi', ['Yalnızca ahşaptan yapılmış olması', 'Kapıların altınla kaplanmış olması', 'Kapıların her yıl yeniden boyanması'], 'Divriği Ulu Camii ve Darüşşifası\'nın taç kapıları taş işçiliğinin doruk örnekleridir ve UNESCO Dünya Mirası Listesi\'ndedir.'),
  ('Lalenin Osmanlı kültüründe çok sevilmesinin ve süslemede sık kullanılmasının ardındaki etkenlerden biri nedir?', 'Ebcet hesabında "lale" ile "Allah" sözcüklerinin harf değerlerinin eşit olması', ['Lalenin Anadolu\'da yetişmeyen yabancı bir çiçek olması', 'Lalenin kokusunun hiçbir çiçeğe benzememesi', 'Lalenin yalnız kış aylarında açması'], 'Arap harfleriyle yazılan "lale" ile "Allah" sözcüklerinin harfleri aynıdır ve ebcet değerleri eşittir. Ayrıca "lale" tersine okunduğunda "hilal" sözcüğünü çağrıştırır.'),
  ('Osmanlı İstanbul\'unda geceleri elindeki sopayı yere vurarak sokakları dolaşan ve güvenliği sağlayan bekçiye ne ad verilirdi?', 'Pazvant', ['Tulumbacı', 'Kalaycı', 'Cambaz'], 'Pazvantlar, sopalarının sesiyle hırsızları ürkütür ve halka uyanık olduklarını duyururdu.'),
  ('"Cambaz" sözcüğü kökeninde ip üstünde gösteri yapanlardan önce hangi meslek için kullanılırdı?', 'At alım satımı yapan tüccar', ['Kervanlara rehberlik eden kılavuz', 'Saray mutfağında çalışan aşçı', 'Gemilerde yelken onaran tayfa'], 'Cambaz önceleri at ticareti yapan kişiydi; sonradan ip cambazı gibi ustalık gösterileri yapan sanatçılar için de kullanılır oldu.'),
  ('Selçuklu kervansaraylarında yolcuların genellikle üç gün boyunca ücretsiz ağırlanması ticaret açısından hangi sonucu doğurmuştur?', 'Tüccarların Anadolu yollarını güvenle tercih etmesi', ['Kervansarayların yalnızca devlet memurlarına açılması', 'Ticaretin Anadolu dışına kayması', 'Kervanların yollarda hiç konaklamaması'], 'Güvenli ve ücretsiz konaklama, yolculuğun maliyetini ve riskini azaltmış; bu da Anadolu\'nun uluslararası ticarette önemini artırmıştır.'),
  ('"Akıllı düşman akılsız dosttan iyidir." atasözünün dayandığı düşünce nedir?', 'Akılsız bir dostun yanlışları, akıllı bir düşmanın planlarından daha çok zarar verebilir.', ['Düşmanlarla her zaman dost olunmalı ve güvenilmelidir.', 'Akıllı insanların dostu hiçbir zaman olmaz.', 'Dostluk yalnızca aynı yaştaki insanlar arasında kurulur.'], 'Akıllı düşmanın davranışı öngörülebilir; akılsız dost ise iyi niyetle bile beklenmedik zararlara yol açabilir.'),
  ('Semazenin giydiği siyah hırkayı törenin başında çıkarması nasıl yorumlanır?', 'Dünya bağlarından sıyrılıp manevi olarak yeniden doğmak', ['Törenin bittiğini seyircilere duyurmak', 'Dönüşe başlamadan önce ısınmak', 'Yeni katılan semazenlere hırkayı armağan etmek'], 'Siyah hırka mezarı simgeler; hırkadan sıyrılan semazen beyaz tennuresiyle bir tür arınmış, yeniden doğmuş hâli temsil eder.'),
  ('Mevlevi seması ile Alevi semahını karşılaştıran bir öğrencinin yaptığı tespitlerden hangisi doğrudur?', 'Semada ney ve kudüm, semahta ise bağlama ön plandadır.', ['Semah yalnız erkeklerle, sema ise yalnız kadınlarla yapılır.', 'İkisinde de hiçbir çalgı kullanılmaz, yalnız el çırpılır.', 'Sema açık havada, semah ise yalnızca camilerde yapılır.'], 'Mevlevi ayininde ney, kudüm, rebap gibi çalgılar kullanılır; semahta ise bağlama esastır ve kadınlarla erkekler birlikte döner.'),
  ('Ankara keçisinin uzun ve parlak yününden elde edilen, eskiden Ankara\'da dokunan değerli kumaşa ne ad verilir?', 'Sof', ['Kutnu', 'Kadife', 'Çuha'], 'Ankara keçisinin tiftiğinden dokunan sof, Osmanlı döneminde Avrupa\'ya ihraç edilen ünlü bir kumaştı.'),
  ('Gaziantep\'te ipek ve pamuk ipliklerinin birlikte kullanılmasıyla dokunan, çizgili desenleriyle tanınan kumaş hangisidir?', 'Kutnu', ['Sof', 'Şile bezi', 'Ehram'], 'Kutnu kumaşı Gaziantep\'e özgüdür ve coğrafi işaret almıştır. Parlak görünümü ipekten, dayanıklılığı pamuktan gelir.'),
  ('Bir girişimci, Tokat dışında üretilen makine baskısı kumaşlara "Tokat yazması" adını verip satmak istiyor. Coğrafi işaret sistemine göre bu durum için ne söylenebilir?', 'Tescilli adın yöre dışında ve kurallara aykırı üretilen ürünlerde kullanılması coğrafi işaret hakkının ihlalidir.', ['Ürünün adı herkesçe serbestçe kullanılabilir.', 'Makine baskısı ürünler her zaman coğrafi işaretli sayılır.', 'Ad yalnızca yabancı ülkelerde korunur.'], 'Coğrafi işaret, ürün adını tescile uygun üretimle sınırlar. Böylece yöresel ürünün ünü ve üreticisi korunmuş olur.'),
  ('Siirt\'te tiftik keçisi yününden dokunan ve coğrafi işaretle korunan ürün hangisidir?', 'Battaniye', ['Halı', 'Seccade ya da kilim', 'Çorap'], 'Siirt battaniyesi, yöreye özgü tiftik yününden elde edilir; sıcak tutması ve yumuşaklığıyla bilinir.'),
  ('Kahvenin yerini büyük ölçüde çayın alması 20. yüzyıl Türkiye\'sinde hangi gelişmeyle bağlantılıdır?', 'Yurt içinde çay üretiminin başlaması ve kahvenin pahalılaşması', ['Kahvenin sağlığa zararlı olduğunun yasayla duyurulması', 'Çayın yalnız yabancı turistlere satılması', 'Kahvehanelerin tümüyle kapatılması'], 'Rize\'de çay tarımının gelişmesiyle çay ucuz ve yerli bir içecek olmuş; ithal edilen kahve ise pahalılaşmıştır.'),
  ('Oğuz boylarının her birinin kutsal saydığı ve etini yemedikleri kuşa ne ad verilirdi?', 'Ongun', ['Tuğ', 'Tamga ya da damga', 'Yuğ'], 'Ongun, boyu koruduğuna inanılan totem niteliğinde bir hayvandır. Oğuz boylarının ongunları çoğunlukla yırtıcı kuşlardır.'),
  ('Eski Türk inancında Gök Tanrı anlayışı ile hükümdarın konumu arasındaki ilişki en doğru biçimde hangisiyle açıklanır?', 'Hükümdar yetkisini Tanrı\'dan aldığına inanılan kut ile meşrulaştırırdı.', ['Hükümdar Tanrı\'nın kendisi olarak görülür ve tapınılırdı.', 'Hükümdar halk tarafından her yıl yeniden seçilirdi.', 'Hükümdarın dinle hiçbir bağı olmadığı kabul edilirdi.'], 'Kut inancına göre yönetme yetkisi gökten verilir; kutunu yitiren hükümdarın tahtı da tehlikeye girerdi.'),
  ('Göktürk Kitabeleri\'nin eski Türkçede taşıdığı adın "bengü taş" olması, bu yazıtlara verilen hangi anlamı yansıtır?', 'Sözlerin sonsuza dek kalması isteğini', ['Taşın değerli bir maden olmasını', 'Yazıtların kısa süreli olmasını', 'Taşların yalnız mezar olarak kullanılmasını'], 'Bengü "ebedî, sonsuz" demektir. Bilge Kağan ve Kül Tigin yazıtları geleceğe kalıcı bir öğüt bırakmak amacıyla dikilmiştir.'),
  ('Eski Türklerde ordu düzenine benzer biçimde, büyük bir alan çember içine alınarak yapılan toplu av hangi adla anılır?', 'Sığır', ['Toy', 'Yuğ', 'Şölen ya da toy'], 'Sığır avı, bir eğlence olmanın yanı sıra askerlerin savaş düzeni ve disiplin içinde hareket etmeyi öğrendiği bir tatbikattı.'),
  ('Eski Türklerde yönler renklerle anılırdı. Bu geleneğe göre "Karadeniz" ve "Akdeniz" adlarındaki renkler hangi yönleri gösterir?', 'Kara kuzeyi, ak batıyı', ['Kara doğuyu, ak ise güneyi gösterir', 'Kara batıyı, ak kuzeyi', 'Kara güneyi, ak doğuyu'], 'Eski Türk yön simgeciliğinde kara kuzeyi, ak batıyı, kızıl güneyi, gök de doğuyu anlatır. Anadolu\'nun kuzeyindeki deniz Kara, batısındaki Ak diye anılmıştır.'),
  ('Eski Türk yön-renk simgeciliğine göre güney yönü hangi renkle anılırdı?', 'Kızıl', ['Gök', 'Ak', 'Kara ya da koyu'], 'Güney kızıl renkle eşleştirilirdi. "Kızıldeniz" adının bu anlayışla ilişkilendirilmesi de bu yüzdendir.'),
  ('"Dadaloğlu" mahlasıyla tanınan, Toroslardaki Türkmen aşiretlerinin iskân politikasına karşı direnişini şiirlerinde anlatan âşık hangi yüzyılda yaşamıştır?', '19. yüzyıl', ['15. yüzyılın sonları', '16. yüzyıl', '20. yüzyıl'], 'Dadaloğlu 19. yüzyılda yaşamış Avşar Türkmeni bir âşıktır. "Ferman padişahın, dağlar bizimdir" dizesiyle bilinir.'),
  ('Karagöz oyunlarında süslü giyinen, kibar konuşan, çoğu zaman zengin bir babanın oğlu olarak çıkan züppe tip hangisidir?', 'Çelebi', ['Tuzsuz Deli Bekir', 'Beberuhi', 'Tiryaki'], 'Çelebi, İstanbullu ağzıyla konuşan, gösterişe meraklı bir gençtir. Kadınlara kur yapar ve çoğu zaman alaya alınır.'),
  ('Halk oyunlarının bulunduğu yörenin coğrafyası ve yaşam biçimiyle ilişkisini en iyi gösteren örnek hangisidir?', 'Teke oyunlarında dağ keçisinin sıçrayışlarının taklit edilmesi', ['Bütün yörelerde aynı oyunun aynı biçimde oynanması', 'Halk oyunlarının yalnızca saray çevrelerinde ortaya çıkıp yayılması', 'Oyunların hiçbir çalgı olmadan, sessizce oynanması'], 'Halk oyunları yörenin doğasını, geçim kaynaklarını ve hayvanlarını yansıtır. Hayvancılıkla geçinen Teke yöresinde oyunlar keçinin hareketlerinden esinlenir.'),
  ('Ahilik teşkilatında üyelerin akşamları bir araya gelip sohbet ettiği, konuk ağırladığı ve eğitim gördüğü yere ne ad verilir?', 'Zaviye', ['Bedesten', 'Kervansaray', 'Darphane'], 'Ahi zaviyeleri hem konuk evi hem de meslek ve ahlak eğitiminin verildiği toplanma yerleriydi. İbn Battuta, Anadolu\'daki bu konukseverliği övmüştür.'),
  ('İbn Battuta\'nın 14. yüzyılda Anadolu\'yu gezerken Ahiler hakkında en çok övdüğü özellik hangisidir?', 'Yabancı yolculara gösterdikleri konukseverlik', ['Savaşlarda gösterdikleri yiğitlik', 'Saray mimarisindeki ustalıkları', 'Deniz ticaretindeki başarıları'], 'İbn Battuta, uğradığı her kentte Ahilerin kendisini zaviyelerinde ağırlamak için yarıştığını anlatır.'),
  ('Halk takviminde Ekim sonu ile Kasım başında koçların koyun sürüsüne katılması geleneğine ne ad verilir?', 'Koç katımı', ['Saya gezmesi', 'Kırkım', 'Sağım'], 'Koç katımı, kuzuların ilkbaharda, otların yeşerdiği dönemde doğmasını sağlamak için yapılır ve köylerde şenliklerle kutlanır.'),
  ('Koç katımının sonbaharın sonunda yapılmasının hayvancılık açısından nedeni nedir?', 'Kuzuların otların bol olduğu ilkbaharda doğması', ['Koyunların kışın daha çok süt vermesi', 'Koçların yazın çok sıcaktan etkilenmesi', 'Çobanların kışın işsiz kalmaması'], 'Koyunların gebelik süresi yaklaşık beş aydır. Sonbahar sonunda yapılan katımla kuzular ilkbaharda doğar ve bol otla beslenir.'),
  ('Kütahya\'nın bugün çini ve seramik üretiminin en önemli merkezlerinden biri olmasının tarihî arka planı hangisidir?', 'İznik atölyeleri gerileyince üretimin büyük ölçüde Kütahya\'da sürmesi', ['Kütahya\'nın Osmanlı\'nın ilk başkenti olması', 'Kütahya\'da hiç kil bulunmaması', 'Çininin ilk kez Kütahya\'da icat edilmesi'], '17. yüzyıldan sonra İznik\'te üretim azalırken Kütahya atölyeleri gelişmiş ve gelenek bu kentte kesintisiz sürmüştür.'),
  ('Çini yapımında desenin hamura aktarılması için delikli kâğıt üzerine kömür tozu serpilmesi tekniğine ne denir?', 'Silkme', ['Sırlama', 'Pişirme', 'Astarlama'], 'Silkmede desen kâğıda çizilip çizgiler iğneyle delinir; kâğıt yüzeye konup kömür tozu serpilince desen yüzeye geçer.'),
  ('Hızla yaygınlaşan makine baskılı halılar karşısında el dokuması halıcılığın değerini koruması için en etkili yaklaşım hangisi olabilir?', 'Kök boya ve geleneksel motif gibi özgün nitelikleri belgeleyip tanıtmak', ['El dokumasını tümüyle makine üretimiyle değiştirmek', 'Geleneksel motifleri yasaklayıp yenilerini zorunlu kılmak', 'El dokuması halıları yalnızca müzelerde saklamak'], 'El dokumasının değeri özgünlüğünden gelir. Coğrafi işaret, sertifika ve tanıtım bu niteliklerin farkını görünür kılar.'),
  ('Ebru sanatı UNESCO İnsanlığın Somut Olmayan Kültürel Mirası Temsili Listesi\'ne Türkiye adına hangi yıl alınmıştır?', '2014', ['2008', '2011', '2019'], 'Ebru, Türk kâğıt süsleme sanatı olarak 2014\'te listeye girmiştir.'),
  ('Ebru teknesinde boyalar serpildikten sonra bir tel ya da bizle dalgalı çizgiler çizilmesiyle elde edilen desenli ebru türüne ne denir?', 'Gelgit ebru', ['Battal ebru ya da kumlu ebru', 'Akkase ebru', 'Kumlu ebru'], 'Gelgit ebruda boyalar ileri geri çekilerek dalga deseni oluşturulur. Battal ebru ise hiç biçim verilmeden alınan temel ebrudur.'),
  ('Ebru ile yapılan kâğıtların eskiden kitap ciltlerinde ve resmî belgelerde de kullanılmasının nedeni ne olabilir?', 'Her ebrunun tek ve yinelenemez olması, sahteciliği zorlaştırması', ['Ebrunun su geçirmez bir kâğıt olması', 'Ebru kâğıdının hiç yanmaması', 'Ebru kâğıdının çok ucuz olması'], 'Ebru deseni aynen tekrarlanamaz. Bu yüzden ciltleri süslemenin yanında belgelerin üzerine yazının taklit edilmesini de güçleştirirdi.'),
  ('Minyatür sanatçılarının eserlerinde altın ve lapis lazuli gibi pahalı malzemeleri kullanabilmesinin en önemli nedeni nedir?', 'Sarayın ve devlet büyüklerinin hamiliği', ['Bu malzemelerin çok ucuz olması', 'Sanatçıların kendi madenlerini işletmesi', 'Malzemelerin yalnızca kumdan elde edilmesi'], 'Minyatürler çoğunlukla saray nakkaşhanesinde, padişah ve devlet ricalinin desteğiyle hazırlanırdı.'),
];
